read_sheet.source:
async function run(input, tools) {
  const settings = (input && input.settings) || {};
  const sheet = settings.sheet_tab || settings.sheet || "";
  const rows = (sheet ? (await tools.sheets.read({ sheet })).rows : []) || [];

  const column_totals = {};
  let hasNum = {};
  for (const r of rows) {
    if (!r || typeof r !== "object") continue;
    for (const k of Object.keys(r)) {
      const v = r[k];
      const n = typeof v === "number" ? v : (typeof v === "string" && v.trim() !== "" && isFinite(Number(v)) ? Number(v) : null);
      if (n !== null) {
        column_totals[k] = (column_totals[k] || 0) + n;
        hasNum[k] = true;
      }
    }
  }
  const row_count = rows.length;

  let yesterday = input && input.memory ? input.memory.yesterday : undefined;
  if (yesterday === undefined || yesterday === null) {
    try {
      const got = await tools.memory.get({ key: "yesterday" });
      yesterday = got ? got.value : undefined;
    } catch (e) {
      yesterday = undefined;
    }
  }

  const round = (n) => Math.round(n * 100) / 100;
  const fmt = (n) => (n > 0 ? "+" : "") + round(n);

  const column_changes = {};
  let new_rows = 0;
  let lines = [];

  const y = yesterday && typeof yesterday === "object" ? yesterday : null;
  if (!y || typeof y.rows !== "number") {
    new_rows = row_count;
    for (const k of Object.keys(column_totals)) column_changes[k] = round(column_totals[k]);
    lines.push("First run: no yesterday saved, so no comparison.");
    lines.push(`Rows: ${row_count}`);
    const keys = Object.keys(column_totals);
    if (keys.length) {
      lines.push("Totals: " + keys.map((k) => `${k} ${round(column_totals[k])}`).join(", "));
    }
  } else {
    new_rows = row_count - y.rows;
    const prev = y.totals && typeof y.totals === "object" ? y.totals : {};
    const all = new Set([...Object.keys(column_totals), ...Object.keys(prev)]);
    for (const k of all) {
      const cur = column_totals[k] || 0;
      const old = typeof prev[k] === "number" ? prev[k] : 0;
      column_changes[k] = round(cur - old);
    }
    lines.push(`Rows: ${row_count} (${fmt(new_rows)} vs yesterday)`);
    const changed = Object.keys(column_changes).filter((k) => column_changes[k] !== 0);
    if (changed.length) {
      lines.push("Changes: " + changed.map((k) => `${k} ${fmt(column_changes[k])}`).join(", "));
    } else {
      lines.push("No column total changes.");
    }
  }

  return {
    row_count,
    column_totals,
    new_rows,
    column_changes,
    summary_text: lines.join("\n"),
  };
}

save_state.source:
async function run(input, tools) {
  const rows = Number.isFinite(Number(input.row_count)) ? Number(input.row_count) : 0;
  const totals = {};
  const raw = input.column_totals;
  if (raw && typeof raw === "object" && !Array.isArray(raw)) {
    for (const [k, v] of Object.entries(raw)) {
      totals[k] = Number.isFinite(Number(v)) ? Number(v) : 0;
    }
  }
  await tools.memory.set({ key: "yesterday", value: { rows, totals } });
  return {};
}
